cd /testbed && rustc --edition=2021 -g -L dependency=target/debug/deps --extern tokio=target/debug/deps/libtokio-2ecfcbc5cd5841c0.rlib -o target/broadcast_closed_repro - <<'RS'
use tokio::sync::broadcast;

#[tokio::main]
async fn main() {
    let (tx, rx) = broadcast::channel::<u32>(4);
    drop(tx);
    let mut rx_clone = rx.resubscribe();
    drop(rx);
    println!("try_recv: {:?}", rx_clone.try_recv());
    println!("waiting for recv");
    println!("recv: {:?}", rx_clone.recv().await);
}
RS
if [ -x target/broadcast_closed_repro ]; then timeout 3s target/broadcast_closed_repro; result=$?; echo "reproducer exit status: $result"; fi

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tokio/tests/sync_broadcast.rs')
text = path.read_text()
text += '''
#[test]
fn resubscribe_closed() {
    for &capacity in &[1, 4] {
        for messages in 0..=capacity + 1 {
            let (tx, rx) = broadcast::channel(capacity);
            for value in 0..messages {
                assert_ok!(tx.send(value));
            }
            drop(tx);

            let mut rx_resub = rx.resubscribe();
            drop(rx);
            assert_closed!(rx_resub.try_recv());

            let mut rx_resub = rx_resub.resubscribe();
            assert_closed!(rx_resub.try_recv());
        }
    }
}

#[test]
fn resubscribe_closed_recv() {
    for &capacity in &[1, 4] {
        for messages in 0..=capacity + 1 {
            let (tx, rx) = broadcast::channel(capacity);
            for value in 0..messages {
                assert_ok!(tx.send(value));
            }
            drop(tx);

            let mut rx_resub = rx.resubscribe();
            drop(rx);
            let mut recv = task::spawn(rx_resub.recv());
            assert!(is_closed(assert_ready_err!(recv.poll())));
        }
    }
}
'''
path.write_text(text)
PY
cargo test --test sync_broadcast --features full resubscribe_closed -- --nocapture > target/broadcast_baseline.log 2>&1; result=$?; tail -45 target/broadcast_baseline.log; exit "$result"

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tokio/src/sync/broadcast.rs')
text = path.read_text()
old = '''    let next = tail.pos;

    drop(tail);

    Receiver { shared, next }
'''
new = '''    // A closed channel's tail points just past the close signal.
    let next = if tail.closed {
        tail.pos.wrapping_sub(1)
    } else {
        tail.pos
    };

    drop(tail);

    Receiver { shared, next }
'''
assert text.count(old) == 1
text = text.replace(old, new)
old = '''    /// in the queue of the current receiver. Consider the following example.
    ///
    /// # Examples
'''
new = '''    /// in the queue of the current receiver. Consider the following example.
    ///
    /// If the channel is closed, the returned receiver will also be closed.
    ///
    /// # Examples
'''
assert text.count(old) == 1
text = text.replace(old, new)
path.write_text(text)
PY
cargo test --test sync_broadcast --features full > target/broadcast_validation.log 2>&1; result=$?; tail -36 target/broadcast_validation.log; exit "$result"

cd /testbed && rustc --edition=2021 -g -L dependency=target/debug/deps --extern tokio=target/debug/deps/libtokio-2ecfcbc5cd5841c0.rlib -o target/broadcast_closed_repro - <<'RS'
use tokio::sync::broadcast;

#[tokio::main]
async fn main() {
    let (tx, rx) = broadcast::channel::<u32>(4);
    drop(tx);
    let mut rx_clone = rx.resubscribe();
    drop(rx);
    if std::env::args().any(|arg| arg == "try_recv") {
        assert_eq!(rx_clone.try_recv(), Err(broadcast::error::TryRecvError::Closed));
        println!("try_recv: Closed");
    } else {
        assert_eq!(rx_clone.recv().await, Err(broadcast::error::RecvError::Closed));
        println!("recv: Closed");
    }
    println!("Done");
}
RS
timeout 3s target/broadcast_closed_repro && timeout 3s target/broadcast_closed_repro try_recv && rm target/broadcast_closed_repro target/broadcast_baseline.log target/broadcast_validation.log && git diff --check && git --no-pager diff --stat && git --no-pager diff -- tokio/src/sync/broadcast.rs tokio/tests/sync_broadcast.rs

